{
  "id": "job-progress-panel",
  "name": "Job Progress Panel",
  "description": "聊天区右侧的任务进度面板：按 job_id 合并 app.job.progress 业务事件，分别展示多个任务的进度、完成状态与可展开的失败原因。",
  "version": "0.0.1",
  "capabilities": [
    "job-progress-panel"
  ],
  "data": {
    "events": [
      "app.job.progress"
    ]
  },
  "authoring": {
    "intents": [
      "show job progress panel on the right of the chat area",
      "显示任务进度面板",
      "在聊天区域右侧显示任务进度",
      "查看多个后台任务的进度与失败原因"
    ],
    "visualRole": "chat area right side job progress panel",
    "recommendedSize": {
      "width": "320px"
    }
  }
}

import type { UIPluginDefinition, UIPluginManifest } from "@za38.03/agent-ui-plugins";
import manifestJson from "./manifest.json";
import { JobProgressPanelPlugin } from "./index";

const definition: UIPluginDefinition = {
  manifest: manifestJson as UIPluginManifest,
  provides: [],
  inject: [],
  optionalInject: ["agent-ui.locale"],
  Component: JobProgressPanelPlugin,
};

export default definition;

import { useAgentUILocaleCode, usePluginEvents } from "@za38.03/agent-ui-plugins";
import { useEffect, useMemo, useState } from "react";
import "./styles.css";

type JobError = { code?: string; message?: string } | null;

/** Business payload carried by the live `app.job.progress` application event. */
type JobProgressEventPayload = {
  job_id?: string;
  title?: string;
  status?: string;
  completed?: number;
  total?: number;
  error?: JobError;
};

type JobProgress = {
  jobId: string;
  title: string;
  status: string;
  completed: number;
  total: number;
  error: JobError;
};

type StatusKind = "pending" | "running" | "completed" | "failed" | "cancelled";

type Messages = {
  title: string;
  summary: (active: number, all: number) => string;
  emptyTitle: string;
  emptyHint: string;
  steps: (completed: number, total: number) => string;
  unbounded: string;
  status: Record<StatusKind, string>;
  errorToggle: string;
  errorCode: string;
  errorMessage: string;
};

const messages: Record<string, Messages> = {
  "zh-CN": {
    title: "任务进度",
    summary: (active, all) => (active > 0 ? `${active} 个进行中 / 共 ${all} 个` : `共 ${all} 个任务`),
    emptyTitle: "暂无任务",
    emptyHint: "Agent 汇报任务进度后，这里会按任务实时更新。",
    steps: (completed, total) => `${completed} / ${total} 步`,
    unbounded: "进度暂未提供",
    status: {
      pending: "等待中",
      running: "进行中",
      completed: "已完成",
      failed: "失败",
      cancelled: "已取消",
    },
    errorToggle: "查看错误原因",
    errorCode: "错误码",
    errorMessage: "错误原因",
  },
  "en-US": {
    title: "Job progress",
    summary: (active, all) => (active > 0 ? `${active} running of ${all}` : `${all} jobs`),
    emptyTitle: "No jobs yet",
    emptyHint: "Jobs appear here and update in place once the Agent reports progress.",
    steps: (completed, total) => `${completed} / ${total} steps`,
    unbounded: "Progress unavailable",
    status: {
      pending: "Pending",
      running: "Running",
      completed: "Completed",
      failed: "Failed",
      cancelled: "Cancelled",
    },
    errorToggle: "Show error details",
    errorCode: "Code",
    errorMessage: "Reason",
  },
};

const STATUS_ALIASES: Record<string, StatusKind> = {
  pending: "pending",
  queued: "pending",
  waiting: "pending",
  created: "pending",
  scheduled: "pending",
  running: "running",
  in_progress: "running",
  processing: "running",
  started: "running",
  active: "running",
  completed: "completed",
  complete: "completed",
  succeeded: "completed",
  success: "completed",
  done: "completed",
  finished: "completed",
  failed: "failed",
  failure: "failed",
  error: "failed",
  errored: "failed",
  cancelled: "cancelled",
  canceled: "cancelled",
  aborted: "cancelled",
};

function normalizeStatus(status: string | undefined): StatusKind {
  if (!status) return "running";
  return STATUS_ALIASES[status.trim().toLowerCase()] ?? "running";
}

function normalizeNumber(value: number | undefined, fallback: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.max(0, value);
}

function normalizeError(error: JobError | undefined): JobError {
  if (!error) return null;
  const code = typeof error.code === "string" && error.code.trim() ? error.code.trim() : undefined;
  const message = typeof error.message === "string" && error.message.trim() ? error.message.trim() : undefined;
  if (!code && !message) return null;
  return { ...(code ? { code } : {}), ...(message ? { message } : {}) };
}

function progressPercent(job: JobProgress): number {
  if (job.total > 0) {
    return Math.min(100, Math.max(0, Math.round((job.completed / job.total) * 100)));
  }
  return normalizeStatus(job.status) === "completed" ? 100 : 0;
}

export function JobProgressPanelPlugin() {
  const events = usePluginEvents();
  const localeCode = useAgentUILocaleCode();
  const text = messages[localeCode] ?? messages["zh-CN"]!;
  const [jobs, setJobs] = useState<JobProgress[]>([]);

  useEffect(
    () =>
      events.subscribe<JobProgressEventPayload>("app.job.progress", (event) => {
        const payload = event?.payload;
        const jobId = typeof payload?.job_id === "string" ? payload.job_id.trim() : "";
        if (!jobId) return;
        const hasErrorKey = Object.prototype.hasOwnProperty.call(payload, "error");

        setJobs((previous) => {
          const index = previous.findIndex((job) => job.jobId === jobId);
          const base: JobProgress =
            index >= 0
              ? previous[index]!
              : { jobId, title: jobId, status: "running", completed: 0, total: 0, error: null };

          const title =
            typeof payload.title === "string" && payload.title.trim() ? payload.title.trim() : base.title;
          const status =
            typeof payload.status === "string" && payload.status.trim() ? payload.status.trim() : base.status;

          const next: JobProgress = {
            ...base,
            title,
            status,
            completed: normalizeNumber(payload.completed, base.completed),
            total: normalizeNumber(payload.total, base.total),
            error: hasErrorKey ? normalizeError(payload.error) : base.error,
          };

          if (index < 0) return [...previous, next];
          const copy = previous.slice();
          copy[index] = next;
          return copy;
        });
      }),
    [events],
  );

  const activeCount = useMemo(
    () => jobs.filter((job) => normalizeStatus(job.status) === "running").length,
    [jobs],
  );

  return (
    <aside className="job-progress-panel" aria-label={text.title}>
      <header className="job-progress-panel__header">
        <h2 className="job-progress-panel__title">{text.title}</h2>
        {jobs.length > 0 ? (
          <span className="job-progress-panel__summary" aria-live="polite">
            {text.summary(activeCount, jobs.length)}
          </span>
        ) : null}
      </header>
      {jobs.length === 0 ? (
        <div className="job-progress-panel__empty">
          <p className="job-progress-panel__empty-title">{text.emptyTitle}</p>
          <p className="job-progress-panel__empty-hint">{text.emptyHint}</p>
        </div>
      ) : (
        <ul className="job-progress-panel__list">
          {jobs.map((job) => (
            <JobProgressItem key={job.jobId} job={job} text={text} />
          ))}
        </ul>
      )}
    </aside>
  );
}

function JobProgressItem({ job, text }: { job: JobProgress; text: Messages }) {
  const kind = normalizeStatus(job.status);
  const percent = progressPercent(job);
  const indeterminate = kind === "running" && job.total <= 0;
  const errorCode = job.error?.code;
  const errorMessage = job.error?.message;
  const hasError = Boolean(errorCode || errorMessage);

  return (
    <li className="job-progress-panel__item" data-status={kind}>
      <div className="job-progress-panel__item-head">
        <span className="job-progress-panel__job-title" title={job.title}>
          {job.title}
        </span>
        <span className="job-progress-panel__badge">{text.status[kind]}</span>
      </div>
      <div
        className={`job-progress-panel__bar${indeterminate ? " job-progress-panel__bar--indeterminate" : ""}`}
        role="progressbar"
        aria-label={job.title}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={indeterminate ? undefined : percent}
      >
        <span
          className="job-progress-panel__bar-fill"
          style={{ width: indeterminate ? "35%" : `${percent}%` }}
        />
      </div>
      <div className="job-progress-panel__meta">
        <span>{job.total > 0 ? text.steps(job.completed, job.total) : text.unbounded}</span>
        <span>{indeterminate ? text.status.running : `${percent}%`}</span>
      </div>
      {hasError ? (
        <details className="job-progress-panel__error">
          <summary className="job-progress-panel__error-summary">{text.errorToggle}</summary>
          <dl className="job-progress-panel__error-body">
            {errorCode ? (
              <>
                <dt>{text.errorCode}</dt>
                <dd>{errorCode}</dd>
              </>
            ) : null}
            {errorMessage ? (
              <>
                <dt>{text.errorMessage}</dt>
                <dd>{errorMessage}</dd>
              </>
            ) : null}
          </dl>
        </details>
      ) : null}
    </li>
  );
}

.job-progress-panel {
  --job-progress-success: var(--success, #0f7b4f);
  --job-progress-danger: var(--destructive, #b42318);
  --job-progress-running: var(--primary, #3757d5);
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  background: var(--background);
  color: var(--foreground);
  border-left: 1px solid var(--border);
}

.job-progress-panel__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  flex: 0 0 auto;
  min-width: 0;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
}

.job-progress-panel__title {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.job-progress-panel__summary {
  flex: 0 0 auto;
  font-size: 12px;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
  white-space: nowrap;
}

.job-progress-panel__empty {
  flex: 1 1 auto;
  min-height: 0;
  padding: 20px 16px;
  overflow-y: auto;
}

.job-progress-panel__empty-title {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 500;
}

.job-progress-panel__empty-hint {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
  overflow-wrap: anywhere;
}

.job-progress-panel__list {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  min-height: 0;
  margin: 0;
  padding: 10px;
  overflow-y: auto;
  list-style: none;
}

.job-progress-panel__item {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--card);
  color: var(--foreground);
}

.job-progress-panel__item-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.job-progress-panel__job-title {
  min-width: 0;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.job-progress-panel__badge {
  flex: 0 0 auto;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--muted);
  font-size: 11px;
  line-height: 1.6;
  white-space: nowrap;
}

.job-progress-panel__item[data-status="running"] .job-progress-panel__badge {
  background: color-mix(in srgb, var(--job-progress-running) 16%, transparent);
  color: var(--job-progress-running);
}

.job-progress-panel__item[data-status="completed"] .job-progress-panel__badge {
  background: color-mix(in srgb, var(--job-progress-success) 16%, transparent);
  color: var(--job-progress-success);
}

.job-progress-panel__item[data-status="failed"] .job-progress-panel__badge {
  background: color-mix(in srgb, var(--job-progress-danger) 16%, transparent);
  color: var(--job-progress-danger);
}

.job-progress-panel__item[data-status="cancelled"] .job-progress-panel__badge {
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
}

.job-progress-panel__bar {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 6px;
  min-width: 0;
  overflow: hidden;
  border-radius: 999px;
  background: var(--muted);
}

.job-progress-panel__bar-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--job-progress-running);
  transition: width 240ms ease;
}

.job-progress-panel__item[data-status="completed"] .job-progress-panel__bar-fill {
  background: var(--job-progress-success);
}

.job-progress-panel__item[data-status="failed"] .job-progress-panel__bar-fill {
  background: var(--job-progress-danger);
}

.job-progress-panel__item[data-status="cancelled"] .job-progress-panel__bar-fill {
  background: color-mix(in srgb, var(--foreground) 35%, transparent);
}

.job-progress-panel__bar--indeterminate .job-progress-panel__bar-fill {
  animation: job-progress-panel-pulse 1.4s ease-in-out infinite;
}

@keyframes job-progress-panel-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .job-progress-panel__bar-fill {
    transition: none;
  }

  .job-progress-panel__bar--indeterminate .job-progress-panel__bar-fill {
    animation: none;
  }
}

.job-progress-panel__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
}

.job-progress-panel__meta > span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.job-progress-panel__error {
  margin-top: 2px;
  padding-top: 6px;
  border-top: 1px dashed var(--border);
}

.job-progress-panel__error-summary {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--job-progress-danger);
  cursor: pointer;
  list-style: none;
}

.job-progress-panel__error-summary::-webkit-details-marker {
  display: none;
}

.job-progress-panel__error-summary::before {
  content: "▸";
  flex: 0 0 auto;
  font-size: 10px;
}

.job-progress-panel__error[open] .job-progress-panel__error-summary::before {
  content: "▾";
}

.job-progress-panel__error-summary:hover {
  text-decoration: underline;
}

.job-progress-panel__error-summary:focus-visible {
  outline: 2px solid var(--ring, var(--border));
  outline-offset: 2px;
  border-radius: 4px;
}

.job-progress-panel__error-body {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 4px 8px;
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.5;
}

.job-progress-panel__error-body dt {
  font-weight: 500;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
}

.job-progress-panel__error-body dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}

import { z } from "zod";

/**
 * Project-owned business application events.
 *
 * Registered through `<Agent appEventSchemas={agentEventSchemas} />` and declared per
 * consumer Plugin in its manifest `data.events`. These are live notifications only:
 * they do not replay conversation history.
 */
const jobErrorSchema = z
  .object({
    code: z.string().optional(),
    message: z.string().optional(),
  })
  .loose();

export const jobProgressEventSchema = z
  .object({
    job_id: z.string().min(1),
    title: z.string().optional(),
    status: z.string().optional(),
    completed: z.number().optional(),
    total: z.number().optional(),
    error: jobErrorSchema.nullish(),
  })
  .loose();

export const agentEventSchemas = {
  "app.job.progress": jobProgressEventSchema,
};

